const batchId = "BATCH-UAT-001";

const baseCRM = {
  last_contacted_days_ago: 30,
  do_not_contact: false,
  open_opportunity: false,
  existing_customer: false,
  existing_relationship_or_owner: false,
  previous_disqualification: false
};

const prospects = [
  {
    prospect_id: "P-B001",
    company_name: "Aurelius Insurance Group",
    industry: "Insurance",
    employee_count: 8500,
    annual_revenue_gbp: 2400000000,
    primary_erp: "SAP ECC",
    job_title: "Director of Finance Transformation",
    signals: {
      finance_transformation_programme: true,
      erp_migration: true,
      finance_systems_hiring: true
    },
    crm: {
      ...baseCRM
    }
  },
  {
    prospect_id: "P-B002",
    company_name: "Northbridge Manufacturing",
    industry: "Manufacturing",
    employee_count: 4200,
    annual_revenue_gbp: 1100000000,
    primary_erp: "Oracle E-Business Suite",
    job_title: "VP Finance",
    signals: {
      finance_transformation_programme: true,
      erp_migration: true,
      finance_systems_hiring: false
    },
    crm: {
      ...baseCRM,
      open_opportunity: true
    }
  },
  {
    prospect_id: "P-B003",
    company_name: "Westhaven Logistics",
    industry: "Logistics",
    employee_count: 2300,
    annual_revenue_gbp: 580000000,
    primary_erp: "Microsoft Dynamics",
    job_title: "Finance Systems Manager",
    signals: {
      finance_transformation_programme: true,
      erp_migration: false,
      finance_systems_hiring: true
    },
    crm: {
      ...baseCRM,
      last_contacted_days_ago: 5
    }
  },
  {
    prospect_id: "P-B004",
    company_name: "Meridian Retail Holdings",
    industry: "Retail",
    employee_count: 6100,
    annual_revenue_gbp: 1750000000,
    primary_erp: "SAP S/4HANA",
    job_title: "Group Financial Controller",
    signals: {
      finance_transformation_programme: false,
      erp_migration: false,
      finance_systems_hiring: false
    },
    crm: {
      ...baseCRM
    }
  },
  {
    prospect_id: "P-B005",
    company_name: "Crestfield Energy Services",
    industry: "Energy",
    employee_count: 3700,
    annual_revenue_gbp: 890000000,
    primary_erp: "SAP ECC",
    job_title: "Head of Finance Transformation",
    signals: {
      finance_transformation_programme: true,
      erp_migration: true,
      finance_systems_hiring: true
    },
    crm: {
      ...baseCRM,
      existing_relationship_or_owner: true
    }
  }
];

// Prevent ambiguous record matching.
const ids = prospects.map(p => p.prospect_id);

if (new Set(ids).size !== ids.length) {
  throw new Error("DUPLICATE_PROSPECT_ID");
}

if (
  prospects.some(p =>
    typeof p.prospect_id !== "string" ||
    !p.prospect_id.trim()
  )
) {
  throw new Error("INVALID_PROSPECT_ID");
}

// Select exactly one prospect for the live Dust UAT.
const liveProspects = prospects.filter(
  p => p.prospect_id === "P-B002"
);

if (liveProspects.length !== 1) {
  throw new Error("LIVE_UAT_PROSPECT_NOT_FOUND");
}

return liveProspects.map((p, index) => ({
  json: {
    batch_id: "BATCH-LIVE-UAT-002",
    batch_position: index + 1,
    batch_size: liveProspects.length,
    prospect_id: p.prospect_id,
    assessment_mode: "live",
    polling_timeout_ms: 120000,

    account: {
      company_name: p.company_name,
      industry: p.industry,
      employee_count: p.employee_count,
      annual_revenue_gbp: p.annual_revenue_gbp
    },

    finance_environment: {
      primary_erp: p.primary_erp
    },

    transformation_signals: p.signals,

    prospect: {
      job_title: p.job_title
    },

    crm: p.crm
  }
}));

const expected = $("Batch - Generate Synthetic Prospects")
  .all()
  .map(item => item.json);

const received = $input.all().map(item => item.json);

if (expected.length === 0) {
  throw new Error("EMPTY_INPUT_BATCH");
}

if (received.length !== expected.length) {
  throw new Error(
    `RESULT_COUNT_MISMATCH: expected ${expected.length}, received ${received.length}`
  );
}

const allowedStatuses = new Set([
  "COMPLETED",
  "REJECTED",
  "TIMED_OUT",
  "DUST_API_ERROR",
  "PROCESSOR_FAILURE",
  "INVALID_DUST_RESPONSE"
]);

const allowedActions = new Set([
  "QUEUED_PRIORITY",
  "QUEUED_STANDARD",
  "PERSONA_RESEARCH",
  "NURTURE",
  "HELD",
  "NOT_PRIORITISED"
]);

const expectedIds = new Set();
const resultsById = new Map();

for (const source of expected) {
  if (
    typeof source.prospect_id !== "string" ||
    expectedIds.has(source.prospect_id)
  ) {
    throw new Error("INVALID_OR_DUPLICATE_INPUT_ID");
  }
  expectedIds.add(source.prospect_id);
}

for (const result of received) {
  const id = result.prospect_id;

  if (!expectedIds.has(id)) {
    throw new Error(`UNEXPECTED_PROSPECT: ${id}`);
  }

  if (resultsById.has(id)) {
    throw new Error(`DUPLICATE_PROSPECT_RESULT: ${id}`);
  }

  if (!allowedStatuses.has(result.processing_status)) {
    throw new Error(`INVALID_PROCESSING_STATUS: ${id}`);
  }

  if (result.processing_status === "COMPLETED") {
    if (!allowedActions.has(result.action_outcome)) {
      throw new Error(`INVALID_COMPLETED_ACTION: ${id}`);
    }

    if (result.error_code != null) {
      throw new Error(`COMPLETED_WITH_ERROR: ${id}`);
    }
  } else {
    if (result.action_outcome != null) {
      throw new Error(`FAILED_WITH_BUSINESS_ACTION: ${id}`);
    }

    if (
      typeof result.error_code !== "string" ||
      !result.error_code.trim()
    ) {
      throw new Error(`MISSING_FAILURE_ERROR_CODE: ${id}`);
    }
  }

  resultsById.set(id, result);
}

for (const source of expected) {
  const result = resultsById.get(source.prospect_id);

  if (!result) {
    throw new Error(
      `MISSING_PROSPECT_RESULT: ${source.prospect_id}`
    );
  }

  if (
    result.batch_id !== source.batch_id ||
    result.batch_position !== source.batch_position ||
    result.batch_size !== source.batch_size
  ) {
    throw new Error(
      `BATCH_IDENTITY_MISMATCH: ${source.prospect_id}`
    );
  }
}

// Restore the original input order.
const ordered = expected.map(source =>
  resultsById.get(source.prospect_id)
);

const count = status =>
  ordered.filter(r => r.processing_status === status).length;

return [{
  json: {
    batch_id: expected[0].batch_id,
    total_prospects: expected.length,
    completed: count("COMPLETED"),
    rejected: count("REJECTED"),
    timed_out: count("TIMED_OUT"),
    dust_api_error: count("DUST_API_ERROR"),
    processor_failure: count("PROCESSOR_FAILURE"),
    invalid_dust_response: count("INVALID_DUST_RESPONSE"),
    verification_status: "PASS",
    results: ordered
  }
}];

const input = $input.all();

if (input.length !== 1) {
  throw new Error("EXPECTED_ONE_VERIFIED_BATCH");
}

const report = input[0].json;

if (report.verification_status !== "PASS") {
  throw new Error("BATCH_VERIFICATION_NOT_PASSED");
}

const results = report.results;

if (
  !Array.isArray(results) ||
  results.length === 0 ||
  results.length !== report.total_prospects
) {
  throw new Error("INVALID_BATCH_RESULTS");
}

// All six supported technical processing statuses.
// Includes invalid responses from live Dust assessments.
const allowedStatuses = [
  "COMPLETED",
  "REJECTED",
  "TIMED_OUT",
  "DUST_API_ERROR",
  "PROCESSOR_FAILURE",
  "INVALID_DUST_RESPONSE"
];

const allowedActions = [
  "QUEUED_PRIORITY",
  "QUEUED_STANDARD",
  "PERSONA_RESEARCH",
  "NURTURE",
  "HELD",
  "NOT_PRIORITISED"
];

const statusCounts = Object.fromEntries(
  allowedStatuses.map(s => [s, 0])
);

const actionCounts = Object.fromEntries(
  allowedActions.map(a => [a, 0])
);

const errorCounts = {};
const ids = new Set();

const dispositions = {
  ADD_TO_PRIORITY_OUTBOUND_QUEUE: "QUEUED_PRIORITY",
  ADD_TO_STANDARD_OUTBOUND_QUEUE: "QUEUED_STANDARD",
  RESEARCH_BETTER_PERSONA: "PERSONA_RESEARCH",
  NURTURE_OR_MONITOR: "NURTURE",
  HOLD: "HELD",
  DO_NOT_PRIORITISE: "NOT_PRIORITISED"
};

for (const r of results) {
  if (
    typeof r.prospect_id !== "string" ||
    !r.prospect_id.trim() ||
    ids.has(r.prospect_id) ||
    r.batch_id !== report.batch_id ||
    !allowedStatuses.includes(r.processing_status)
  ) {
    throw new Error("INVALID_OR_DUPLICATE_BATCH_RESULT");
  }

  ids.add(r.prospect_id);

  statusCounts[r.processing_status]++;

  if (r.processing_status === "COMPLETED") {
    if (
      !allowedActions.includes(r.action_outcome) ||
      dispositions[r.outreach_disposition] !== r.action_outcome ||
      r.error_code !== null ||
      r.final_validation_status !== "PASS"
    ) {
      throw new Error(
        `INVALID_COMPLETED_RESULT:${r.prospect_id}`
      );
    }

    actionCounts[r.action_outcome]++;

  } else {
    // Technical failures must never authorise
    // a business action or outbound disposition.
    if (
      r.action_outcome !== null ||
      r.outreach_disposition !== null ||
      typeof r.error_code !== "string" ||
      !r.error_code.trim()
    ) {
      throw new Error(
        `INVALID_FAILED_RESULT:${r.prospect_id}`
      );
    }

    errorCounts[r.error_code] =
      (errorCounts[r.error_code] || 0) + 1;
  }
}

const successful = statusCounts.COMPLETED;
const failed = results.length - successful;

return [{
  json: {
    batch_id: report.batch_id,
    total_prospects: results.length,
    successful,
    failed,
    status_counts: statusCounts,
    action_outcome_counts: actionCounts,
    error_counts: errorCounts,
    batch_status:
      failed === 0 ? "COMPLETED" :
      successful === 0 ? "FAILED" :
      "PARTIAL_SUCCESS",
    verification_status: "PASS",
    completed_at: new Date().toISOString(),
    results
  }
}];

const items = $input.all();

const errorPrefix = "UAT_FORCED_PROCESSOR_FAILURE";

return items.map((item, index) => {
  const source = item.json;

  // Preserve the identity supplied by n8n's
  // error output, rather than reconstructing it
  // from execution order or an AI response.
  if (
    typeof source.batch_id !== "string" ||
    !source.batch_id.trim() ||
    typeof source.prospect_id !== "string" ||
    !source.prospect_id.trim() ||
    !Number.isInteger(source.batch_position) ||
    !Number.isInteger(source.batch_size)
  ) {
    throw new Error(
      "UNRECOVERABLE_PROCESSOR_IDENTITY"
    );
  }

  const errorMessage =
    typeof source.error === "string"
      ? source.error
      : source.error?.message;

  if (
    typeof errorMessage !== "string" ||
    !errorMessage.trim()
  ) {
    throw new Error(
      "MISSING_PROCESSOR_ERROR_MESSAGE"
    );
  }

  const isForcedTest =
    errorMessage.includes(errorPrefix);

  return {
    json: {
      batch_id: source.batch_id,
      batch_position: source.batch_position,
      batch_size: source.batch_size,
      prospect_id: source.prospect_id,
    assessment_mode:
  ["mock", "live"].includes(source.assessment_mode)
    ? source.assessment_mode
    : null,
      processing_status: "PROCESSOR_FAILURE",
      action_outcome: null,
      outreach_disposition: null,

      suppression_source: null,
      suppression_reason: null,

      error_code: isForcedTest
        ? errorPrefix
        : "UNEXPECTED_PROCESSOR_ERROR",

      error_detail: errorMessage,

      decision_summary:
        "Prospect assessment failed unexpectedly. " +
        "No business action was authorised.",

      dust_conversation_id:
  typeof source.dust_conversation_id === "string" &&
  source.dust_conversation_id.trim()
    ? source.dust_conversation_id
    : null,
      processed_at: new Date().toISOString()
    },
    pairedItem: { item: index }
  };
});

const items = $input.all();

// Stage 19: Batch safety limits.
const MAX_MOCK_BATCH_SIZE = 25;
const MAX_LIVE_BATCH_SIZE = 5;

// Reject empty batches.
if (items.length === 0) {
  throw new Error("EMPTY_BATCH");
}

const records = items.map(item => item.json);

// Resolve the mode from the first record.
// Mock remains the default for reproducible UAT.
const assessmentMode =
  records[0]?.assessment_mode ?? "mock";

if (
  assessmentMode !== "mock" &&
  assessmentMode !== "live"
) {
  throw new Error("INVALID_BATCH_ASSESSMENT_MODE");
}

const maxBatchSize =
  assessmentMode === "live"
    ? MAX_LIVE_BATCH_SIZE
    : MAX_MOCK_BATCH_SIZE;

// Enforce the limit before processing any prospect.
if (items.length > maxBatchSize) {
  throw new Error(
    `BATCH_SIZE_LIMIT_EXCEEDED: ` +
    `${items.length} records supplied; ` +
    `maximum ${maxBatchSize} for ${assessmentMode}`
  );
}

const batchId = records[0]?.batch_id;
const seenProspectIds = new Set();

if (
  typeof batchId !== "string" ||
  !batchId.trim()
) {
  throw new Error("INVALID_BATCH_ID");
}

for (let index = 0; index < records.length; index++) {
  const record = records[index];

  if (
    !record ||
    typeof record !== "object" ||
    Array.isArray(record)
  ) {
    throw new Error(
      `INVALID_BATCH_RECORD: position ${index + 1}`
    );
  }

  // All records must belong to the same batch.
  if (record.batch_id !== batchId) {
    throw new Error("MIXED_BATCH_IDENTIFIERS");
  }

  // Prevent accidental mixing of mock and live.
  const recordMode =
    record.assessment_mode ?? "mock";

  if (recordMode !== assessmentMode) {
    throw new Error("MIXED_ASSESSMENT_MODES");
  }

  // Enforce the existing one-based batch convention.
  if (
    !Number.isInteger(record.batch_position) ||
    record.batch_position !== index + 1
  ) {
    throw new Error(
      `INVALID_BATCH_POSITION: ${index + 1}`
    );
  }

  if (
    !Number.isInteger(record.batch_size) ||
    record.batch_size !== items.length
  ) {
    throw new Error("INCONSISTENT_BATCH_SIZE");
  }

  // Require a valid, unique prospect identity.
  if (
    typeof record.prospect_id !== "string" ||
    !record.prospect_id.trim()
  ) {
    throw new Error("INVALID_PROSPECT_ID");
  }

  if (seenProspectIds.has(record.prospect_id)) {
    throw new Error(
      `DUPLICATE_PROSPECT_ID: ${record.prospect_id}`
    );
  }

  seenProspectIds.add(record.prospect_id);

  // CRM context is mandatory for deterministic
  // governance, regardless of assessment mode.
  if (
    !record.crm ||
    typeof record.crm !== "object" ||
    Array.isArray(record.crm)
  ) {
    throw new Error(
      `MISSING_CRM_CONTEXT: ${record.prospect_id}`
    );
  }

  // Validate optional polling configuration.
  if (record.polling_timeout_ms != null) {
    const timeout = record.polling_timeout_ms;

    if (
      typeof timeout !== "number" ||
      !Number.isInteger(timeout) ||
      timeout < 1000 ||
      timeout > 120000
    ) {
      throw new Error(
        `INVALID_POLLING_TIMEOUT: ${record.prospect_id}`
      );
    }
  }
}

// Preserve the original data unchanged.
// Maintain pairing with each input item.
return items.map((item, index) => ({
  json: { ...item.json },
  pairedItem: { item: index }
}));
